// cu2rv DSL 語料（tools/build.js 由 kernels/*.ku 產生，勿手動編輯）
// web/app.js 優先用它覆蓋 DSL 下拉選單。
globalThis.RVJS_KUCORPUS = [
  { name: "relu", src: "# relu.ku — if/else 示範：y[i] = max(0, x[i])\n# 展示區域變數＋條件分支＋自動記憶體配置（無 @ 即從 0x100 起接續）\nlanes 4;\nn 8;\nmem x[8] = i - 4;\nmem y[8];\nkernel relu {\n  for (i: int = tid; i < n; i += ntid) {\n    v: int = x[i];\n    if (v < 0) {\n      y[i] = 0;\n    } else {\n      y[i] = v;\n    }\n  }\n  barrier();\n}\nexpect {\n  y[0] = 0;\n  y[3] = 0;\n  y[4] = 0;\n  y[7] = 3;\n}\n" },
  { name: "saxpy", src: "# saxpy.ku — 常數縮放加法：C[i] = a*A[i] + B[i]（a=2）\n# 展示 param＋func 真實呼叫＋grid-stride loop\nlanes 4;\nn 8;\nmem A[8] @ 0x100 = i + 1;\nmem B[8] @ 0x120 = i + 2;\nmem C[8] @ 0x140;\nparam a: int = 2;\nfunc axpy(a: int, xi: int, yi: int) -> int {\n  t: int = a * xi;\n  return t + yi;\n}\nkernel saxpy {\n  for (i: int = tid; i < n; i += ntid) {\n    C[i] = axpy(a, A[i], B[i]);\n  }\n  barrier();\n}\nexpect {\n  C[i] = 2 * A[i] + B[i];\n}\n" },
  { name: "sum", src: "# sum.ku — reduction 示範：total[0] = sum(x)\n# 各通道先部分和 → partial[tid] → barrier → lane0 加總\nlanes 4;\nn 16;\nmem x[16] = i + 1;\nmem partial[4];\nmem total[1];\nkernel sum {\n  s: int = 0;\n  for (i: int = tid; i < n; i += ntid) {\n    s = s + x[i];\n  }\n  partial[tid] = s;\n  barrier();\n  if (tid == 0) {\n    t: int = 0;\n    for (k: int = 0; k < ntid; k += 1) {\n      t = t + partial[k];\n    }\n    total[0] = t;\n  }\n}\nexpect {\n  total[0] = 136;\n}\n" },
  { name: "tiny", src: "# tiny.ku — 單通道最小例（供 rvemu 單通道自檢：tid=0、ntid=1）\n# lanes=1 時單通道算完全部元素，expect 全過，exit=0\nlanes 1;\nn 2;\nmem A[2] @ 0x100 = i + 1;\nmem B[2] @ 0x120 = 10 * (i + 1);\nmem C[2] @ 0x140;\nkernel tiny {\n  for (i: int = tid; i < n; i += ntid) {\n    C[i] = A[i] + B[i];\n  }\n  barrier();\n}\nexpect {\n  C[i] = A[i] + B[i];\n}\n" },
  { name: "vecadd", src: "# vecadd.ku — 向量加法（語意同 riscvgpu/prog.s：C[i]=A[i]+B[i]）\n# A[i]=i+1、B[i]=10*(i+1)、C[i]=11*(i+1)；n=8。\n# 驗證鏈：node cli/cu2rv.js kernels/vecadd.ku -o /tmp/vecadd.s\n#   → node cli/rvasm.js /tmp/vecadd.s → 暫代 prog.hex 跑 iverilog（見 kernels/README.md）\nlanes 4;\nn 8;\nmem A[8] @ 0x100 = i + 1;\nmem B[8] @ 0x120 = 10 * (i + 1);\nmem C[8] @ 0x140;\nkernel vecadd {\n  for (i: int = tid; i < n; i += ntid) {\n    C[i] = A[i] + B[i];\n  }\n  barrier();\n}\nexpect {\n  C[i] = A[i] + B[i];\n}\n" }
];
